    <FormSection title="Identité" description="La vérité corporate qui suit le client dans tout le Revenue Relationship Graph."><Field label="Nom commercial" wide><input value={text(form.display_name)} onChange={(e) => update('display_name', e.target.value)}/></Field><Field label="Raison sociale"><input value={text(form.legal_name)} onChange={(e) => update('legal_name', e.target.value)}/></Field><Select label="Type" value={text(form.client_type)} options={GROWTH_FORM_CATALOGUES.clientTypes} onChange={(value) => update('client_type', value)}/><Field label="Code client"><input value={text(form.client_code)} onChange={(e) => update('client_code', e.target.value)}/></Field><Field label="Ville"><input value={text(form.city)} onChange={(e) => update('city', e.target.value)}/></Field><Field label="Pays"><input value={text(form.country)} onChange={(e) => update('country', e.target.value)}/></Field></FormSection>
