function OpportunityEditor({ form, update, snapshot, stage }: FormProps & { snapshot: GrowthWorkspaceSnapshot; stage: number }) {
  const stages = portalStages('opportunity')
  return <div className={styles.missionEditor}>
    <div className={styles.missionEditorHeader}><Target size={22}/><div><span>Opportunity command portal</span><h3>{stages[stage]}</h3><p>Deal gouverné: account, valeur, solution, stakeholders, risques et next event.</p></div></div>
    {stage === 0 ? <FormSection title="Compte & mission" description="Une seule identité prospect ou client."><AccountSelectors form={form} update={update} snapshot={snapshot}/><Field label="Nom du deal" wide><input value={text(form.name)} onChange={(e) => update('name', e.target.value)}/></Field><Field label="Objectif commercial" wide><textarea value={text(form.objective)} onChange={(e) => update('objective', e.target.value)}/></Field><Select label="Étape" value={text(form.stage)} options={[...OPPORTUNITY_STAGES]} labels={OPPORTUNITY_STAGE_LABELS} onChange={(value) => update('stage', value)}/></FormSection> : null}
    {stage === 1 ? <FormSection title="Valeur & horizon" description="Séparer MRR, ARR, probabilité et date cible."><Field label="MRR attendu"><input type="number" value={numberValue(form.expected_mrr_mad)} onChange={(e) => update('expected_mrr_mad', e.target.value)}/></Field><Field label="ARR attendu"><input type="number" value={numberValue(form.expected_arr_mad)} onChange={(e) => update('expected_arr_mad', e.target.value)}/></Field><Field label="Probabilité"><input type="number" min="0" max="100" value={numberValue(form.probability)} onChange={(e) => update('probability', e.target.value)}/></Field><Field label="Clôture cible"><input type="date" value={dateValue(form.expected_close_date)} onChange={(e) => update('expected_close_date', e.target.value || null)}/></Field><ProductSelector label="Package envisagé" value={text(form.package_version_id)} products={snapshot.products.filter((item) => item.type === 'package')} onChange={(value) => update('package_version_id', value || null)}/></FormSection> : null}
    {stage === 2 ? <FormSection title="Stakeholders & concurrence" description="La couverture décisionnelle est nécessaire avant le closing."><EntitySelect label="Owner" value={text(form.owner_id)} rows={[]} labelKeys={['display_name']} onChange={(value) => update('owner_id', value || null)} emptyLabel="Owner directory non exposé"/><Field label="Concurrence" wide><textarea value={text(form.competition)} onChange={(e) => update('competition', e.target.value)}/></Field><Field label="Risques" wide><textarea value={arrayText(form.risks)} onChange={(e) => update('risks', splitList(e.target.value))}/></Field></FormSection> : null}
    {stage === 3 ? <FormSection title="Prochain événement" description="Aucun deal actif sans action, owner et échéance."><Field label="Next event" wide><input value={text(form.next_event)} onChange={(e) => update('next_event', e.target.value)}/></Field><Field label="Date"><input type="datetime-local" value={dateTimeValue(form.next_event_at)} onChange={(e) => update('next_event_at', e.target.value || null)}/></Field><Field label="Motif / preuve" wide><textarea value={text(form.reason)} onChange={(e) => update('reason', e.target.value)}/></Field></FormSection> : null}
  </div>
}

