  if (entity === 'support_entitlement') return <FormArchitecture title="Contract-Based Support Entitlement" intro="Coverage, SLA, channels, hours and escalation derived from the contract."><FormSection title="Service rights" description="Every case receives the applicable contractual entitlement automatically.">{clientControl}<EntitySelect label="Contract" value={text(form.contract_id)} rows={snapshot.contracts} labelKeys={['contract_code','status']} onChange={(value) => update('contract_id', value || null)}/><EntitySelect label="Subscription" value={text(form.subscription_id)} rows={snapshot.subscriptions} labelKeys={['subscription_code','status']} onChange={(value) => update('subscription_id', value || null)}/><Select label="Support tier" value={text(form.support_tier)} options={['standard','priority','premium','dedicated','custom']} onChange={(value) => update('support_tier', value)}/><Select label="Status" value={text(form.status)} options={['draft','active','suspended','expired','retired']} onChange={(value) => update('status', value)}/><Field label="Included hours"><input type="number" value={numberValue(form.included_hours)} onChange={(e) => update('included_hours', e.target.value)}/></Field><Field label="Consumed hours"><input type="number" value={numberValue(form.consumed_hours)} onChange={(e) => update('consumed_hours', e.target.value)}/></Field><Field label="Response target (minutes)"><input type="number" value={numberValue(form.response_target_minutes)} onChange={(e) => update('response_target_minutes', e.target.value)}/></Field><Field label="Resolution target (minutes)"><input type="number" value={numberValue(form.resolution_target_minutes)} onChange={(e) => update('resolution_target_minutes', e.target.value)}/></Field><Field label="Covered modules" wide><textarea value={arrayText(form.covered_modules)} onChange={(e) => update('covered_modules', splitList(e.target.value))}/></Field><Field label="Support channels" wide><textarea value={arrayText(form.support_channels)} onChange={(e) => update('support_channels', splitList(e.target.value))}/></Field><Select label="Escalation level" value={text(form.escalation_level)} options={['standard','management','executive','critical']} onChange={(value) => update('escalation_level', value)}/><Select label="Out-of-scope policy" value={text(form.out_of_scope_policy)} options={['reject','quote','billable','approval_required']} onChange={(value) => update('out_of_scope_policy', value)}/></FormSection></FormArchitecture>
