function ScoreField({ label, value, onChange }: { label: string; value: unknown; onChange: (value: number) => void }) { const score = Number(value || 0); return <label className={styles.field}><span>{label} · {score}/100</span><input type="range" min="0" max="100" step="5" value={score} onChange={(e) => onChange(Number(e.target.value))}/></label> }
function safeJson(value: string) { try { return JSON.parse(value || '{}') as Record<string, unknown> } catch { return {} } }
function safeJsonArray(value: string) { try { const parsed = JSON.parse(value || '[]'); return Array.isArray(parsed) ? parsed : [] } catch { return [] } }

function AccountSelectors({ form, update, snapshot }: { form: Record<string, unknown>; update: (key: string, value: unknown) => void; snapshot: GrowthWorkspaceSnapshot }) { return <><ClientSelect value={text(form.client_id)} clients={snapshot.clients} onChange={(value) => { update('client_id', value || null); if (value) update('prospect_id', null) }}/><EntitySelect label="Prospect" value={text(form.prospect_id)} rows={snapshot.prospects} labelKeys={['organization_name','prospect_code']} onChange={(value) => { update('prospect_id', value || null); if (value) update('client_id', null) }}/></> }
function ClientSelect({ value, clients, onChange }: { value: string; clients: Array<Record<string, unknown>>; onChange: (value: string) => void }) { return <EntitySelect label="Client" value={value} rows={clients} labelKeys={['display_name','client_code']} onChange={onChange}/> }
function EntitySelect({ label, value, rows, labelKeys, onChange, emptyLabel = 'Sélectionner…' }: { label: string; value: string; rows: Array<Record<string, unknown>> | Array<any>; labelKeys: string[]; onChange: (value: string) => void; emptyLabel?: string }) { return <label className={styles.field}><span>{label}</span><select value={value} onChange={(e) => onChange(e.target.value)}><option value="">{emptyLabel}</option>{rows.map((row: Record<string, unknown>) => <option key={text(row.id)} value={text(row.id)}>{labelKeys.map((key) => text(row[key])).filter(Boolean).join(' · ') || 'Sans libellé'}</option>)}</select></label> }
function ProductSelector({ label, value, products, onChange, useName = false }: { label: string; value: string; products: GrowthWorkspaceSnapshot['products']; onChange: (value: string) => void; useName?: boolean }) { return <label className={styles.field}><span>{label}</span><select value={value} onChange={(e) => onChange(e.target.value)}><option value="">Sélectionner…</option>{products.map((item) => <option key={item.id} value={useName ? item.name : item.id}>{item.name} · {item.detail}</option>)}</select></label> }
function Select({ label, value, options, labels, onChange }: { label: string; value: string; options: readonly string[]; labels?: Record<string, string>; onChange: (value: string) => void }) { return <label className={styles.field}><span>{label}</span><select value={value} onChange={(e) => onChange(e.target.value)}>{options.map((option) => <option key={option} value={option}>{labels?.[option] || human(option)}</option>)}</select></label> }
function Field({ label, wide, children }: { label: string; wide?: boolean; children: React.ReactNode }) { return <label className={styles.field} data-wide={wide}><span>{label}</span>{children}</label> }
function Toggle({ label, checked, onChange }: { label: string; checked: boolean; onChange: (value: boolean) => void }) { return <label className={styles.toggleField}><input type="checkbox" checked={checked} onChange={(e) => onChange(e.target.checked)}/><i/><span>{label}</span></label> }
function FormArchitecture({ title, intro, children }: { title: string; intro: string; children: React.ReactNode }) { return <div className={styles.formArchitecture}><div className={styles.formArchitectureTitle}><span>Purpose-built workspace</span><h3>{title}</h3><p>{intro}</p></div>{children}</div> }
function FormSection({ title, description, children }: { title: string; description: string; children: React.ReactNode }) { return <section className={styles.formSection}><header><span>{title}</span><p>{description}</p></header><div className={styles.formGrid}>{children}</div></section> }

type FormProps = { form: Record<string, unknown>; update: (key: string, value: unknown) => void }

function operationFor(state: GrowthPortalState) {
  if (state.entity === 'contract' && state.mode === 'activate') return 'contract.activate'
  if (state.entity === 'subscription' && state.mode === 'inspect') return ''
  if (state.mode === 'convert') return state.entity === 'prospect' ? 'prospect.convert' : 'offer.convert_contract'
  if (state.mode === 'transition') return `${state.entity}.transition`
  if (state.mode === 'delete') return `${state.entity}.delete`
  if (state.mode === 'create') return `${state.entity}.create`
  if (state.mode === 'edit') return `${state.entity}.update`
  return ''
}

function payloadFor(state: GrowthPortalState, form: Record<string, unknown>) {
  if (state.entity === 'contract' && state.mode === 'activate') return { ...form, contractId: form.id, packageVersionId: form.packageVersionId || null }
  if (state.mode === 'transition') return { id: form.id, status: state.entity === 'opportunity' ? form.status || form.stage : form.status, reason: form.reason }
  return form
}

function defaultsFor(entity: GrowthEntityType | undefined, snapshot: GrowthWorkspaceSnapshot): Record<string, unknown> {
  const now = new Date().toISOString().slice(0, 16)
  const firstClient = snapshot.clients[0]
  if (entity === 'client') return { status: 'active', lifecycle_stage: 'operational', health_status: 'new', risk_level: 'low', country: 'Maroc' }
  if (entity === 'prospect') return { status: 'new', qualification_stage: 'target', country: 'Maroc', pain_points: [], product_fit: {}, potential_mrr_mad: 0 }
  if (entity === 'contact') return { client_id: firstClient?.id || null, role_type: 'influencer', influence_level: 'medium', decision_authority: 'influencer', relationship_strength: 'developing', position: 'neutral', status: 'active', is_primary: false, communication_preferences: {} }
  if (entity === 'institution') return { client_id: firstClient?.id || null, institution_type: 'school', status: 'active', country: 'Maroc', metadata: {} }
  if (entity === 'opportunity') return { client_id: firstClient?.id || null, stage: 'identified', status: 'active', probability: 20, expected_mrr_mad: 0, expected_arr_mad: 0, product_configuration: {}, risks: [] }
  if (entity === 'stakeholder') return { influence_level: 'medium', decision_position: 'neutral', engagement_state: 'unknown', required_for_close: false }
  if (entity === 'offer') return { client_id: firstClient?.id || null, status: 'draft', approval_status: 'pending', monthly_price_mad: 0, annual_price_mad: 0, setup_fee_mad: 0, discount_mad: 0, contract_value_mad: 0, contract_duration_months: 12, configuration_snapshot: {}, value_case: {} }
  if (entity === 'negotiation') return { client_id: firstClient?.id || null, event_type: 'meeting', occurred_at: now, financial_impact_mad: 0 }
  if (entity === 'case') return { client_id: firstClient?.id || null, case_type: 'support_ticket', source_channel: 'internal', status: 'received', severity: 'medium', priority: 'normal', reopened_count: 0 }
  if (entity === 'interaction') return { client_id: firstClient?.id || null, interaction_type: 'meeting', occurred_at: now }
  if (entity === 'expansion') return { client_id: firstClient?.id || null, opportunity_type: 'package_upgrade', status: 'identified', expected_mrr_mad: 0, evidence: {} }
  if (entity === 'intervention') return { client_id: firstClient?.id || null, intervention_type: 'customer_health_recovery', status: 'identified', priority: 'high', financial_exposure_mad: 0, action_plan: [] }
  if (entity === 'account_plan') return { client_id: firstClient?.id || null, title: 'Plan de compte stratégique', status: 'active', horizon_months: 36, ambition_mad: 0, current_footprint: {}, potential_footprint: {}, strategic_priorities: [], whitespace_opportunities: [], stakeholder_strategy: {}, milestones: [] }
  if (entity === 'relationship_coverage') return { client_id: firstClient?.id || null, status: 'active', executive_sponsor_score: 0, economic_buyer_score: 0, contract_authority_score: 0, operational_champion_score: 0, relationship_recency_score: 0, single_contact_dependency: false, missing_roles: [], risk_signals: [], evidence: {}, assessed_at: new Date().toISOString() }
  if (entity === 'forecast') return { forecast_category: 'pipeline', period_key: `${new Date().getFullYear()}-Q${Math.floor(new Date().getMonth() / 3) + 1}`, seller_amount_mad: 0, manager_amount_mad: 0, confidence: 50, snapshot_at: new Date().toISOString() }
  if (entity === 'approval') return { client_id: firstClient?.id || null, approval_type: 'commercial_exception', status: 'requested', requested_value: {}, policy_limit: {}, financial_impact_mad: 0, required_authority: 'commercial_manager' }
  if (entity === 'change_order') return { client_id: firstClient?.id || null, change_type: 'package_change', status: 'draft', current_state: {}, proposed_state: {}, billing_effect: {}, entitlement_effect: {}, customer_communication_required: true }
  if (entity === 'success_plan') return { client_id: firstClient?.id || null, title: 'Plan de réussite client', status: 'active', objective: '', success_metrics: [], product_capabilities: [], milestones: [], evidence: {} }
  if (entity === 'health_model') return { name: 'AngelCare Customer Health', status: 'active', is_default: true, dimensions: [], thresholds: {}, refresh_cadence: 'daily', recovery_playbooks: {} }
  if (entity === 'support_entitlement') return { client_id: firstClient?.id || null, support_tier: 'standard', status: 'active', covered_modules: [], covered_institutions: [], included_hours: 0, consumed_hours: 0, response_target_minutes: 240, resolution_target_minutes: 1440, support_channels: ['email'], escalation_level: 'standard', business_calendar: {}, out_of_scope_policy: 'approval_required' }
  if (entity === 'escalation') return { client_id: firstClient?.id || null, escalation_type: 'account', status: 'open', severity: 'high', revenue_exposure_mad: 0, relationship_exposure: '', command_team: [], review_cadence: 'daily', exit_criteria: [] }
  return {}
}

function portalStages(entity: GrowthEntityType) { if (entity === 'opportunity') return ['Mission & compte','Valeur & solution','Influence & risques','Next event']; if (entity === 'offer') return ['Problème client','Solution Product Studio','Économie & termes','Approbation']; if (entity === 'case') return ['Réception','Qualification','Ownership & SLA','Resolution & outcome']; return ['Informations'] }
function isStagedEntity(entity: GrowthEntityType, mode: GrowthPortalMode) { return ['opportunity','offer','case'].includes(entity) && ['create','edit'].includes(mode) }
function portalTitle(state: GrowthPortalState | null) { if (!state) return ''; const action = ({ create: 'Créer', edit: 'Modifier', inspect: 'Inspecter', transition: 'Changer le statut', delete: 'Retirer', convert: 'Convertir', activate: 'Activer' } as Record<string,string>)[state.mode]; return `${action} · ${entityLabel(state.entity)}` }
function portalEyebrow(state: GrowthPortalState) { return state.entity === 'case' ? 'Customer Case Command' : state.entity === 'offer' ? 'Solution Engineering Lab' : state.entity === 'opportunity' ? 'Deal Execution Theatre' : state.entity === 'contract' ? 'Activation Architecture' : 'Revenue Relationship Command' }
function portalSubtitle(state: GrowthPortalState) { return ({ client: 'Identité, gouvernance et lifecycle du compte.', prospect: 'Qualification du compte cible avant création du deal.', contact: 'Décision, influence et force de relation.', institution: 'Empreinte institutionnelle reliée au tenant.', opportunity: 'Mission commerciale complète avec next event obligatoire.', stakeholder: 'Rôle réel dans la décision du deal.', offer: 'Configuration Product Studio, économie, valeur et approbation.', negotiation: 'Positions, concessions, limites et impact.', contract: 'Contrat, abonnement et activation.', subscription: 'Abonnement et relation de service.', case: 'Ticket, plainte, incident, SLA, résolution et outcome.', interaction: 'Événement relationnel et engagement suivant.', expansion: 'Croissance du compte par produit, capacité ou institution.', intervention: 'Mission de recovery et résultat vérifiable.', account_plan: 'Ambition, footprint, white-space and quarterly milestones.', relationship_coverage: 'Coverage of sponsor, buyer, authority, champion and recency.', forecast: 'Seller forecast, management override and period snapshot.', approval: 'Policy, authority and economic consequence.', change_order: 'Contract, subscription, billing and entitlement amendment.', success_plan: 'Customer objective, measurable outcome and evidence.', health_model: 'Weights, thresholds and recovery playbooks.', support_entitlement: 'Contractual coverage, SLA, hours and channels.', escalation: 'Account-level command, exposure and exit criteria.' } as Record<string,string>)[state.entity] || '' }
function entityLabel(entity: GrowthEntityType) { return ({ client: 'Client', prospect: 'Compte cible', contact: 'Contact & influence', institution: 'Institution', opportunity: 'Opportunity', stakeholder: 'Stakeholder', offer: 'Offre', negotiation: 'Négociation', contract: 'Contrat', subscription: 'Abonnement', case: 'Cas client', interaction: 'Interaction', expansion: 'Expansion', intervention: 'Intervention', account_plan: 'Plan de compte', relationship_coverage: 'Couverture relationnelle', forecast: 'Forecast', approval: 'Approbation', change_order: 'Change order', success_plan: 'Success plan', health_model: 'Health model', support_entitlement: 'Support entitlement', escalation: 'Escalade' } as Record<string,string>)[entity] }
function submitLabel(state: GrowthPortalState) { if (state.mode === 'delete') return 'Confirmer'; if (state.mode === 'transition') return 'Appliquer'; if (state.mode === 'convert') return 'Convertir'; if (state.mode === 'activate') return 'Activer abonnement'; return state.mode === 'create' ? 'Créer & auditer' : 'Enregistrer & synchroniser' }
function footerConsequence(state: GrowthPortalState) { if (state.mode === 'delete') return 'Relations vérifiées avant suppression'; if (state.mode === 'convert') return 'Continuité du graphe préservée'; if (state.mode === 'activate') return 'Abonnement créé et contrat relié'; return 'Mutation réelle + refresh + audit' }
function resolveAccountLabel(form: Record<string, unknown>, snapshot: GrowthWorkspaceSnapshot) { const client = snapshot.clients.find((item) => text(item.id) === text(form.client_id || form.clientId)); if (client) return text(client.display_name); const prospect = snapshot.prospects.find((item) => item.id === text(form.prospect_id)); return prospect?.organization_name || 'Contexte à sélectionner' }
function impactCounts(entity: GrowthEntityType, form: Record<string, unknown>, snapshot: GrowthWorkspaceSnapshot): Array<[string,string]> { const id = text(form.id); const clientId = text(form.client_id || (entity === 'client' ? id : '')); const opportunityId = text(form.opportunity_id || (entity === 'opportunity' ? id : '')); const offerId = text(form.offer_id || (entity === 'offer' ? id : '')); return [['Client', clientId ? resolveClient(clientId, snapshot) : '—'], ['Opportunités', String(snapshot.opportunities.filter((item) => item.client_id === clientId || item.id === opportunityId).length)], ['Offres', String(snapshot.offers.filter((item) => item.client_id === clientId || item.opportunity_id === opportunityId || item.id === offerId).length)], ['Contrats', String(snapshot.contracts.filter((item) => text(item.client_id) === clientId).length)], ['Abonnements', String(snapshot.subscriptions.filter((item) => text(item.client_id) === clientId).length)], ['Cas clients', String(snapshot.cases.filter((item) => item.client_id === clientId).length)]] }
function sidecarRecommendation(state: GrowthPortalState, form: Record<string, unknown>, snapshot: GrowthWorkspaceSnapshot) { if (state.entity === 'opportunity' && !form.next_event) return 'Ajoutez un next event et une date cible avant de maintenir le deal actif.'; if (state.entity === 'offer' && !form.package_version_id) return 'Sélectionnez un package publié pour garantir la compatibilité avec Product Studio.'; if (state.entity === 'case' && !form.due_at) return 'Définissez une échéance ou documentez pourquoi aucun SLA ne s’applique.'; if (state.entity === 'contact' && form.decision_authority === 'final_authority') return 'Reliez cette autorité finale aux opportunités ouvertes du compte.'; if (state.entity === 'client' && snapshot.contacts.filter((item) => item.client_id === form.id).length === 0) return 'Le client ne possède aucun stakeholder structuré.'; return 'Vérifiez les relations affichées, puis exécutez la mutation avec un motif utile.' }
function primaryLabel(form: Record<string, unknown>) { return text(form.display_name || form.organization_name || form.full_name || form.name || form.subject || form.title || form.offer_code || form.contract_code || form.subscription_code || form.case_reference) || 'Objet sans libellé' }
function entityIcon(entity: GrowthEntityType) { const map: Record<GrowthEntityType, React.ReactNode> = { client: <Building2/>, prospect: <Target/>, contact: <UserRound/>, institution: <Building2/>, opportunity: <Target/>, stakeholder: <UsersRound/>, offer: <Sparkles/>, negotiation: <Network/>, contract: <FileSignature/>, subscription: <Layers3/>, case: <MessageSquareWarning/>, interaction: <HeartHandshake/>, expansion: <ArrowRight/>, intervention: <ShieldCheck/>, account_plan: <Target/>, relationship_coverage: <Network/>, forecast: <CircleDollarSign/>, approval: <ShieldCheck/>, change_order: <FileSignature/>, success_plan: <HeartHandshake/>, health_model: <CheckCircle2/>, support_entitlement: <ShieldCheck/>, escalation: <AlertTriangle/> }; return map[entity] }
function resolveClient(id: string, snapshot: GrowthWorkspaceSnapshot) { return text(snapshot.clients.find((item) => text(item.id) === id)?.display_name) || 'Client non résolu' }
function formatValue(value: unknown) { if (Array.isArray(value)) return value.map(String).join(' · '); if (typeof value === 'object') return JSON.stringify(value); if (typeof value === 'boolean') return value ? 'Oui' : 'Non'; return text(value) }
function normalizeRecord(record: Record<string, unknown>) { return { ...record } }
function object(value: unknown) { return value && typeof value === 'object' && !Array.isArray(value) ? value as Record<string, unknown> : {} }
function text(value: unknown) { return value === null || value === undefined ? '' : String(value) }
function human(value: string) { return value.replace(/_/g, ' ').replace(/\b\w/g, (letter) => letter.toUpperCase()) }
function numberValue(value: unknown) { return value === null || value === undefined ? '' : String(value) }
function dateValue(value: unknown) { return value ? text(value).slice(0, 10) : '' }
function dateTimeValue(value: unknown) { return value ? text(value).slice(0, 16) : '' }
function arrayText(value: unknown) { return Array.isArray(value) ? value.join('\n') : text(value) }
function splitList(value: string) { return value.split(/[\n,]/).map((item) => item.trim()).filter(Boolean) }
function money(value: unknown) { const parsed = Number(value || 0); return `${Math.round(Number.isFinite(parsed) ? parsed : 0).toLocaleString('fr-FR')} Dh` }
